// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 450, H = 400;
draw.viewbox(0, 0, W, H).attr('preserveAspectRatio', 'xMidYMid meet');

var PX = 190, PY = 27, L = 155, FW = 95, BR = 13;
var RED = '#c8443c', LITE = '#e9a39c', NAVY = '#1b4f7e', INK = '#1a1a1a';
var SERIF = 'Georgia, "Times New Roman", serif';

var thetaDeg = 25;
var mode = 'Exact: \u2212mg sin \u03B8';

/* ---------- helpers ---------- */
function mlabel(g, str, x, y, size, anchor, color, bold) {
  var t = g.text(str).font({
    family: SERIF, size: size, style: 'italic',
    weight: bold ? 'bold' : 'normal'
  }).fill(color || INK);
  t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 3.4, 'stroke-linejoin': 'round' });
  var b = t.bbox();
  var dx = anchor === 'start' ? 0 : (anchor === 'end' ? -b.width : -b.width / 2);
  var nx = Math.max(4, Math.min(x + dx, W - 4 - b.width));
  var ny = Math.max(2, Math.min(y - b.height / 2, H - 2 - b.height));
  t.move(nx, ny);
  return t;
}
function plabel(g, str, x, y, size, color) {
  var t = g.text(str).font({ family: SERIF, size: size, style: 'normal' }).fill(color || '#333');
  var b = t.bbox();
  t.move(x, y - b.height / 2);
  return t;
}
function arrow(g, x0, y0, dx, dy, len, opts) {
  opts = opts || {};
  var G = g.group();
  if (!(len > 1.5)) return G;
  var m = Math.hypot(dx, dy) || 1, ux = dx / m, uy = dy / m;
  var hl = Math.min(opts.head || 14, len * 0.7), hw = opts.headW || 10.5;
  var tipX = x0 + ux * len, tipY = y0 + uy * len;
  var bX = tipX - ux * hl, bY = tipY - uy * hl;
  var ln = G.line(x0, y0, bX, bY).stroke({ color: opts.color, width: opts.width || 3.4, linecap: 'butt' });
  if (opts.dash) ln.attr('stroke-dasharray', opts.dash);
  G.polygon([[tipX, tipY], [bX - uy * hw / 2, bY + ux * hw / 2], [bX + uy * hw / 2, bY - ux * hw / 2]])
    .fill(opts.color).stroke('none');
  G.remember('tip', [tipX, tipY]);
  return G;
}
function arcPath(cx, cy, r, a0, a1) {
  var p0 = [cx + r * Math.sin(a0), cy + r * Math.cos(a0)];
  var p1 = [cx + r * Math.sin(a1), cy + r * Math.cos(a1)];
  var sweep = (a1 > a0) ? 0 : 1;
  return 'M' + p0[0] + ',' + p0[1] + ' A' + r + ',' + r + ' 0 0 ' + sweep + ' ' + p1[0] + ',' + p1[1];
}
function inter(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () { showPopup(title, body); });
  return el;
}

/* ---------- static scenery ---------- */
var barGrad = draw.gradient('linear', function (add) {
  add.stop(0, '#e6cfa6'); add.stop(1, '#faf2e4');
}).from(0, 0).to(0, 1);
draw.rect(W, 26).fill(barGrad);
draw.line(0, 26, W, 26).stroke({ color: '#e0cfb0', width: 1 });

var bobGrad = draw.gradient('radial', function (add) {
  add.stop(0, '#ffffff'); add.stop(0.5, '#dcdcdc'); add.stop(1, '#7d7d7d');
});
bobGrad.attr({ cx: 0.36, cy: 0.32, r: 0.78, fx: 0.36, fy: 0.32 });

draw.line(PX, PY, PX, PY + L + 28).stroke({ color: '#222', width: 1.6, dasharray: '7,5' });
draw.circle(6).center(PX, PY).fill('#222');
draw.line(PX - 9, PY + L, PX + 9, PY + L).stroke({ color: '#333', width: 1.2 });

var gD = draw.group();

/* ---------- main render ---------- */
function render() {
  gD.clear();
  var th = thetaDeg * Math.PI / 180;
  var s = Math.sin(th), c = Math.cos(th);
  var ux = s, uy = c;            /* radial, pivot -> bob (outward) */
  var tx = c, ty = -s;           /* tangential +x (away from equilibrium for +theta) */
  var bx = PX + L * ux, by = PY + L * uy;
  var sgn = s > 0 ? 1 : (s < 0 ? -1 : 0);
  var sgnL = thetaDeg >= 0 ? 1 : -1;
  var Frad = FW * Math.abs(c);
  var Ftan = FW * Math.abs(s);
  var Flin = FW * Math.min(Math.abs(th), 1.45);
  var tdx = (sgn === 0 ? -tx : -sgn * tx), tdy = (sgn === 0 ? -ty : -sgn * ty);

  var showExact = mode.indexOf('Exact') === 0 || mode.indexOf('Compare') === 0;
  var showLin = mode.indexOf('Small') === 0 || mode.indexOf('Compare') === 0;
  var compare = mode.indexOf('Compare') === 0;

  /* arc s (dashed) through the bob */
  if (Math.abs(thetaDeg) > 0.4) {
    var arcS = gD.path(arcPath(PX, PY, L, 0, th)).fill('none')
      .stroke({ color: '#1a1a1a', width: 1.8, dasharray: '8,5' });
    inter(arcS, 's = L\u03B8  \u2014 arc-length displacement',
      'Arc displacement s',
      'The bob moves along a circular arc of radius L. Its displacement from equilibrium is s = L\u03B8, so a restoring force proportional to \u03B8 is also proportional to s \u2014 the condition for simple harmonic motion.');
  }

  /* string */
  var str = gD.line(PX, PY, bx, by).stroke({ color: INK, width: 2.3, linecap: 'round' });
  inter(str, 'String of length L', 'The string',
    'The inextensible string of length L constrains the bob to a circular arc. Its tension can only pull along its own direction, so it cannot produce any tangential force.');

  /* parallelogram construction of the weight decomposition */
  if (showExact && Math.abs(thetaDeg) > 4) {
    var rt = [bx + ux * Frad, by + uy * Frad];
    var wt = [bx, by + FW];
    var tt = [bx + tdx * Ftan, by + tdy * Ftan];
    gD.line(rt[0], rt[1], wt[0], wt[1]).stroke({ color: '#8a8a8a', width: 1, dasharray: '4,3' });
    gD.line(tt[0], tt[1], wt[0], wt[1]).stroke({ color: '#8a8a8a', width: 1, dasharray: '4,3' });
  }

  /* tension (navy) */
  var aT = arrow(gD, bx, by, -ux, -uy, Frad, { color: NAVY, width: 3.4 });
  inter(aT, 'F_T = mg cos \u03B8 (tension)', 'Tension F_T',
    'Tension acts along the string toward the pivot. It exactly cancels the radial weight component \u2212mg cos \u03B8 (plus supplies the centripetal force when moving), so it never speeds the bob up or slows it down.');

  /* weight */
  var aW = arrow(gD, bx, by, 0, 1, FW, { color: RED, width: 3.4 });
  inter(aW, 'w = mg (weight, always straight down)', 'Weight w = mg',
    'The weight is constant in size and direction. Resolving it into components along the string and tangent to the arc is what reveals the restoring force.');

  /* radial component */
  var aR = arrow(gD, bx, by, ux, uy, Frad, { color: RED, width: 3.2 });
  inter(aR, '\u2212mg cos \u03B8 (radial component)', 'Radial component \u2212mg cos \u03B8',
    'This part of the weight pushes outward along the string and is balanced by the tension. It holds the bob on its circular path but produces no motion along the arc.');

  /* tangential components */
  if (showExact && Ftan > 1.5) {
    var aTan = arrow(gD, bx, by, tdx, tdy, Ftan, { color: RED, width: 3.4 });
    inter(aTan, '\u2212mg sin \u03B8 = ' + (Math.abs(s)).toFixed(3) + ' mg (restoring force)',
      'Tangential component \u2212mg sin \u03B8',
      'This is the only force component along the direction of motion, and the minus sign means it always points back toward \u03B8 = 0. Its size grows with displacement, so it continually drags the bob back through equilibrium.');
  }
  if (showLin && Flin > 1.5) {
    var ox = compare ? ux * 13 : 0, oy = compare ? uy * 13 : 0;
    var aLin = arrow(gD, bx + ox, by + oy, tdx, tdy, Flin,
      { color: compare ? LITE : RED, width: 3.2, dash: compare ? '7,4' : null });
    inter(aLin, '\u2212mg\u03B8 (small-angle / SHM model)', 'Linear model \u2212mg\u03B8',
      'Replacing sin \u03B8 by \u03B8 (radians) gives a force strictly proportional to displacement s = L\u03B8 \u2014 Hooke\u2019s law, hence simple harmonic motion. Below about 15\u00B0 the two arrows are nearly identical; at large angles sin \u03B8 < \u03B8 and the real pendulum is softer.');
  }

  /* bob */
  var bob = gD.circle(2 * BR).center(bx, by).fill(bobGrad).stroke({ color: '#6a6a6a', width: 0.8 });
  inter(bob, 'Bob, mass m', 'The bob',
    'All the mass m is idealised as a point at the end of the string. Only the tangential force component can change its speed along the arc.');

  /* angle arcs */
  if (Math.abs(thetaDeg) > 1.5) {
    gD.path(arcPath(PX, PY, 48, 0, th)).fill('none').stroke({ color: '#222', width: 1.2 });
  }
  if (Math.abs(thetaDeg) > 6) {
    gD.path(arcPath(bx, by, 40, 0, th)).fill('none').stroke({ color: '#222', width: 1.2 });
  }

  /* rotating local axes */
  var AX = 385, AY = 195, AL = 36;
  var axg = gD.group();
  axg.circle(3).center(AX, AY).fill('#333');
  arrow(axg, AX, AY, -ux, -uy, AL, { color: '#111', width: 1.4, head: 9, headW: 7 });
  arrow(axg, AX, AY, tx, ty, AL, { color: '#111', width: 1.4, head: 9, headW: 7 });
  mlabel(axg, '+y', AX - ux * (AL + 13), AY - uy * (AL + 13), 14, 'middle', '#111', true);
  mlabel(axg, '+x', AX + tx * (AL + 14), AY + ty * (AL + 14), 14, 'middle', '#111', true);
  inter(axg, 'Local axes: +y along string, +x tangent to arc', 'Rotating local axes',
    'The natural axes for a pendulum rotate with the string: +y points along the string to the pivot, +x is tangent to the arc. In these axes the weight has components \u2212mg cos \u03B8 (y) and \u2212mg sin \u03B8 (x).');

  /* ---------- labels (drawn last, with white halo) ---------- */
  mlabel(gD, 'L', PX + ux * (L * 0.45) + tx * 16 * sgnL, PY + uy * (L * 0.45) + ty * 16 * sgnL, 16, 'middle');
  if (Math.abs(thetaDeg) > 4) {
    mlabel(gD, '\u03B8', PX + Math.sin(th / 2) * 64, PY + Math.cos(th / 2) * 64, 16, 'middle');
  }
  mlabel(gD, 'm', bx + (BR + 12) * (thetaDeg < -30 ? -1 : 1), by - 4, 16,
    thetaDeg < -30 ? 'end' : 'start');
  if (Math.abs(thetaDeg) > 3) {
    mlabel(gD, 's', PX + Math.sin(th * 0.55) * (L - 20), PY + Math.cos(th * 0.55) * (L - 20), 15, 'middle');
  }
  /* F_T (with subscript) */
  var fmx = bx - ux * Frad * 0.55 + tx * 20, fmy = by - uy * Frad * 0.55 + ty * 20;
  mlabel(gD, 'F', fmx - 4, fmy, 16, 'end', NAVY);
  mlabel(gD, 'T', fmx - 2, fmy + 5, 11, 'start', NAVY);
  /* weight */
  mlabel(gD, 'w = mg', bx, by + FW + 24, 16, 'middle');
  /* radial label */
  if (Math.abs(thetaDeg) > 5) {
    mlabel(gD, '\u2212mg cos \u03B8',
      bx + ux * (Frad + 14) + tx * 26 * sgnL,
      by + uy * (Frad + 14) + ty * 26 * sgnL, 15, 'middle');
    mlabel(gD, '\u03B8', bx + Math.sin(th / 2) * 55, by + Math.cos(th / 2) * 55, 15, 'middle');
  }
  /* tangential labels */
  if (showExact && Ftan > 14) {
    mlabel(gD, '\u2212mg sin \u03B8', bx + tdx * (Ftan + 16), by + tdy * (Ftan + 16) + 14,
      15, tdx < 0 ? 'end' : 'start');
  }
  if (showLin && Flin > 14) {
    var lx = bx + (compare ? ux * 13 : 0) + tdx * (Flin + 16);
    var ly = by + (compare ? uy * 13 : 0) + tdy * (Flin + 16) + (compare ? 30 : 14);
    mlabel(gD, '\u2212mg\u03B8', lx, ly, 15, tdx < 0 ? 'end' : 'start', compare ? '#b06a63' : INK);
  }

  /* ---------- readout panel ---------- */
  var pg = gD.group();
  pg.rect(212, 60).move(8, 328).radius(4).fill('#ffffff').opacity(0.86).stroke({ color: '#dcdcdc', width: 1 });
  var thr = Math.abs(th), sn = Math.abs(s);
  plabel(pg, '\u03B8 = ' + thetaDeg.toFixed(1) + '\u00B0     s = L\u03B8 = ' + thr.toFixed(2) + ' L', 15, 342, 12.5, '#222');
  plabel(pg, 'exact   |\u2212mg sin \u03B8| = ' + sn.toFixed(3) + ' mg', 15, 360, 12.5, RED);
  var l3 = 'linear  |\u2212mg\u03B8| = ' + thr.toFixed(3) + ' mg';
  if (sn > 0.002) l3 += '  (+' + ((thr / sn - 1) * 100).toFixed(1) + '%)';
  plabel(pg, l3, 15, 377, 12.5, '#a8615a');
  inter(pg, 'Numerical readout', 'Reading the numbers',
    'The exact restoring force is mg|sin \u03B8|; the small-angle model gives mg|\u03B8| (radians). The percentage shows how much the linear model over-estimates the force \u2014 under 1% near 15\u00B0, but around 10% at 60\u00B0.');
}

/* ---------- interaction handlers ---------- */
function setTheta(v) {
  thetaDeg = v;
  var inp = document.getElementById('thetaAngleInput');
  var out = document.getElementById('thetaAngleVal');
  if (inp) inp.value = Math.round(v);
  if (out) out.value = v.toFixed(0);
  render();
}
function update_thetaAngle(v) {
  stopSwing();
  setTheta(v);
}
function toggle_forceModel(v) {
  mode = v;
  render();
}

/* animation */
var anim = { on: false, t0: 0, A: 25, raf: 0 };
function startSwing() {
  anim.A = Math.abs(thetaDeg) > 3 ? Math.abs(thetaDeg) : 25;
  anim.on = true;
  anim.t0 = (window.performance || Date).now();
  var b = document.getElementById('swingBtn');
  if (b) { b.textContent = '\u275A\u275A Pause'; b.classList.add('active'); }
  swingLoop();
}
function stopSwing() {
  if (anim.raf) cancelAnimationFrame(anim.raf);
  anim.raf = 0; anim.on = false;
  var b = document.getElementById('swingBtn');
  if (b) { b.textContent = '\u25B6 Release and swing'; b.classList.remove('active'); }
}
function swingLoop() {
  if (!anim.on) return;
  var t = ((window.performance || Date).now() - anim.t0) / 1000;
  var T = 2.3;
  setTheta(anim.A * Math.cos(2 * Math.PI * t / T));
  anim.raf = requestAnimationFrame(swingLoop);
}
function trigger_swing() { anim.on ? stopSwing() : startSwing(); }

/* ---------- demo step player ---------- */
var steps = [
  { title: 'The hanging pendulum',
    narration: 'At \u03B8 = 0 the bob hangs on the dashed vertical: the weight mg points straight down along the string and the tension F_T balances it exactly. There is no tangential arrow, so nothing pushes the bob sideways \u2014 this is equilibrium.',
    state: { thetaAngle: 0, forceModel: 'Exact: \u2212mg sin \u03B8' } },
  { title: 'Pull the bob aside',
    narration: 'Displace the bob to about 25\u00B0. The weight now splits into \u2212mg cos \u03B8 pressing outward along the string (opposed by tension) and \u2212mg sin \u03B8 tangent to the arc, pointing back toward the vertical. Only the tangential piece can change the bob\u2019s speed.',
    state: { thetaAngle: 25, forceModel: 'Exact: \u2212mg sin \u03B8' } },
  { title: 'Sign flips across equilibrium',
    narration: 'Swing the bob to the other side. The tangential arrow reverses direction while the radial arrow does not \u2014 the restoring force always points toward \u03B8 = 0, which is exactly what makes the motion oscillatory.',
    state: { thetaAngle: -40, forceModel: 'Exact: \u2212mg sin \u03B8' } },
  { title: 'Small-angle approximation',
    narration: 'Switch to the compare view at a small angle: sin \u03B8 \u2248 \u03B8, so the exact and linear arrows nearly coincide. The restoring force becomes proportional to displacement s = L\u03B8, the defining condition for simple harmonic motion.',
    state: { thetaAngle: 10, forceModel: 'Compare both' } },
  { title: 'Where the approximation breaks',
    narration: 'Push \u03B8 out to 60\u00B0 and the two arrows separate noticeably \u2014 sin \u03B8 falls well below \u03B8, so the real pendulum is \u201Csofter\u201D than the SHM model and its period lengthens.',
    state: { thetaAngle: 60, forceModel: 'Compare both' } },
  { title: 'Watch it oscillate',
    narration: 'Released! Follow the tangential arrow: it is longest at the turning points, vanishes at the bottom, and reverses each pass \u2014 the force continually chases the bob back toward the center.',
    state: { thetaAngle: 25, forceModel: 'Exact: \u2212mg sin \u03B8' } }
];
var cur = 1;
function setStep(i) {
  cur = (i + steps.length) % steps.length;
  var st = steps[cur];
  stopSwing();
  var sel = document.getElementById('forceModelInput');
  if (sel) sel.value = st.state.forceModel;
  mode = st.state.forceModel;
  setTheta(st.state.thetaAngle);
  var n = document.getElementById('demoNarration');
  if (n) n.innerHTML = '<b>' + st.title + '</b><br>' + st.narration;
  var lab = document.getElementById('stepLabel');
  if (lab) lab.textContent = 'Step ' + (cur + 1) + ' / ' + steps.length;
  if (cur === steps.length - 1) startSwing();
}
function nextStep() { setStep(cur + 1); }
function prevStep() { setStep(cur - 1); }

/* ---------- init ---------- */
render();
setStep(1);
window.__markRendered();
// @FIGURE_CODE_END

